//! One region mechanism for the whole engine.
//!
//! The US, EU and KR ROMs relocate code and move the data segment, so every
//! hardcoded US address the crate touches must be translated for the region
//! whose guest memory is live. [`Rom`] is caller-owned: it rides in the host
//! or context the caller builds (never in a global, never sniffed from
//! memory), and [`addr`] maps a US address to the running region's twin.
//! Unlisted addresses (numeric constants, scratch, guest stack) pass through
//! unchanged in every region.
//!
//! The table is generated by rust/scripts/gen_rom_region.py from
//! eu/kr/data/map.json, kr/data/d_map.json and the containing-function
//! deltas; EU data is US+0x1240 (wire-b2 round 6, content-verified).
//! Leave room for Jp: it fits as a fourth `Rom` variant plus a fourth table
//! column; the match sites below are written to extend that way.
//!
//! Address spaces overlap across regions (e.g. US code 0x15c544 is also the
//! EU twin of the 0x15c480 string; EU code 0x172de0 is the twin of US
//! 0x172d30 while US 0x172de0 lives at EU 0x172e90). Reverse mapping is
//! therefore only correct with the caller's [`Rom`]: [`to_us`] takes it
//! explicitly, and [`Rom::from_entry`] guesses only unambiguous twin
//! values (never a US key), so a guess can fail closed but never misroute.

include!("rom_region_tables.rs");

/// The ROM whose guest memory is live. The caller picks it when it builds
/// the host; US is the default so existing US-only paths are unchanged.
#[derive(Clone, Copy, PartialEq, Eq, Debug, Default)]
pub enum Rom {
    #[default]
    Us,
    Eu,
    Kr,
}

impl Rom {
    /// Prefer a non-US region: `self` when it names a region, else `other`.
    /// Used at dispatch boundaries so an explicitly threaded region wins
    /// over the entry-derived guess.
    pub fn or(self, other: Rom) -> Rom {
        if self != Rom::Us {
            self
        } else {
            other
        }
    }

    /// Guess the region of a guest address: EU/KR only for unambiguous twin
    /// values (an address no US function uses); US otherwise. A guess can
    /// fail closed at an unmapped entry but never reroutes a genuine US
    /// address: US keys always read as US here.
    pub fn from_entry(entry: u32) -> Rom {
        if is_us(entry) {
            return Rom::Us;
        }
        // Binary search the reverse tables (identical semantics to the old
        // linear scan: smallest US wins; EU wins ties in the same row).
        let eu = lookup_eu(entry);
        let kr = lookup_kr(entry);
        match (eu, kr) {
            (Some(a), Some(b)) => {
                if a < b {
                    Rom::Eu
                } else if b < a {
                    Rom::Kr
                } else {
                    Rom::Eu
                }
            }
            (Some(_), None) => Rom::Eu,
            (None, Some(_)) => Rom::Kr,
            (None, None) => Rom::Us,
        }
    }
}

/// Translate a US code or data address to `rom`'s twin. Identity for US and
/// for unlisted addresses.
pub fn addr(rom: Rom, us: u32) -> u32 {
    if rom == Rom::Us {
        return us;
    }
    match REGION_TABLE.binary_search_by_key(&us, |row| row.0) {
        Ok(i) => {
            let (_, eu, kr) = REGION_TABLE[i];
            if rom == Rom::Eu {
                eu
            } else {
                kr
            }
        }
        Err(_) => us,
    }
}

/// Map a possibly relocated guest entry back to the US address the shared
/// ports dispatch on, in the context of `rom`.
///
/// A genuine US entry always maps to itself first (this preserves the old
/// pass-through for colliding numbers like US code 0x15c544, which is also
/// the EU twin of the 0x15c480 string, and keeps every US dispatch
/// bit-identical). Otherwise the running region's column is scanned, so an
/// unambiguous EU/KR twin resolves to its US entry; anything else passes
/// through and surfaces as its own unbound entry instead of misrouting.
pub fn to_us(rom: Rom, entry: u32) -> u32 {
    if is_us(entry) {
        return entry;
    }
    // Binary search the reverse tables. Identical semantics to the old
    // linear scan: US-first (is_us above), then the running region's
    // column; for Us, the smallest US across both columns wins.
    match rom {
        Rom::Us => {
            let eu = lookup_eu(entry);
            let kr = lookup_kr(entry);
            match (eu, kr) {
                (Some(a), Some(b)) => a.min(b),
                (Some(a), None) => a,
                (None, Some(b)) => b,
                (None, None) => entry,
            }
        }
        Rom::Eu => lookup_eu(entry).unwrap_or(entry),
        Rom::Kr => lookup_kr(entry).unwrap_or(entry),
    }
}

fn is_us(address: u32) -> bool {
    REGION_TABLE.binary_search_by_key(&address, |row| row.0).is_ok()
}

/// Smallest US entry whose EU twin is `entry`, via binary search.
/// REGION_BY_EU is sorted by (eu, us), so the lower bound is the
/// linear scan's first-in-US-order win.
fn lookup_eu(entry: u32) -> Option<u32> {
    match REGION_BY_EU.binary_search_by_key(&entry, |row| row.0) {
        Ok(mut i) => {
            while i > 0 && REGION_BY_EU[i - 1].0 == entry {
                i -= 1;
            }
            Some(REGION_BY_EU[i].1)
        }
        Err(_) => None,
    }
}

/// Smallest US entry whose KR twin is `entry`, via binary search.
fn lookup_kr(entry: u32) -> Option<u32> {
    match REGION_BY_KR.binary_search_by_key(&entry, |row| row.0) {
        Ok(mut i) => {
            while i > 0 && REGION_BY_KR[i - 1].0 == entry {
                i -= 1;
            }
            Some(REGION_BY_KR[i].1)
        }
        Err(_) => None,
    }
}

/// Map a guest-sourced code pointer (a vtable slot read from the live
/// arena) back to the US address the shared ports dispatch on.
///
/// Unlike [`to_us`], the running region's column wins over a colliding US
/// key: guest memory holds regional addresses, so EU `0x172de0` (the twin
/// of US `0x172d30`) must map to `0x172d30`, not to the US code at
/// `0x172de0`. Live hardcoded US literals keep using [`to_us`].
pub fn to_us_guest(rom: Rom, entry: u32) -> u32 {
    // Region-first: the running region's column wins over a colliding US
    // key (binary search, identical to the old linear scan).
    match rom {
        Rom::Eu => {
            if let Some(us) = lookup_eu(entry) {
                return us;
            }
        }
        Rom::Kr => {
            if let Some(us) = lookup_kr(entry) {
                return us;
            }
        }
        _ => {}
    }
    if is_us(entry) {
        return entry;
    }
    // Second pass mirrors to_us for the remaining cases (for Eu/Kr the
    // lookup above already missed, so this only matters for Us).
    match rom {
        Rom::Us => {
            let eu = lookup_eu(entry);
            let kr = lookup_kr(entry);
            match (eu, kr) {
                (Some(a), Some(b)) => a.min(b),
                (Some(a), None) => a,
                (None, Some(b)) => b,
                (None, None) => entry,
            }
        }
        Rom::Eu => lookup_eu(entry).unwrap_or(entry),
        Rom::Kr => lookup_kr(entry).unwrap_or(entry),
    }
}
